  1840          case FILE_SEARCH: { /* search ms->search.s for the string m->value.s */
  1841                  size_t slen;
  1842                  size_t idx;
  1843
  1844                  if (ms->search.s == NULL)
  1845                          return 0;
  1846
  1847                  slen = MIN(m->vallen, sizeof(m->value.s));
  1848                  l = 0;
  1849                  v = 0;
