   491  protected int
   492  file_regcomp(file_regex_t *rx, const char *pat, int flags)
   493  {
   494  #ifdef USE_C_LOCALE
   495          rx->c_lc_ctype = newlocale(LC_CTYPE_MASK, "C", 0);
   496          assert(rx->c_lc_ctype != NULL);
