   498          assert(rx->old_lc_ctype != NULL);
   499  #else
   500          rx->old_lc_ctype = setlocale(LC_CTYPE, "C");
   501  #endif
   502          rx->pat = pat;
   503
   504          return rx->rc = regcomp(&rx->rx, pat, flags);
